import { Component } from '@angular/core';
import { RouterLink } from '@angular/router';

@Component({
  selector: 'app-privacy',
  standalone: true,
  imports: [RouterLink],
  template: `
    <div class="legal-page">
      <div class="legal-card">
        <a routerLink="/" class="legal-back">← Back</a>
        <h1>Privacy Policy</h1>
        <p class="legal-updated">Last updated: August 2026</p>

        <h2>1. Information We Collect</h2>
        <p>We collect your name, email, and membership details when you sign up, plus workout data (weight logs, class bookings) you choose to enter.</p>

        <h2>2. How We Use Your Data</h2>
        <p>Your data is used to run your account, manage bookings, share progress with your assigned trainer, and improve our services.</p>

        <h2>3. Data Sharing</h2>
        <p>We do not sell your personal data. Data may be shared with your coach/trainer and payment processors strictly to deliver the service.</p>

        <h2>4. Data Security</h2>
        <p>Passwords are stored hashed, never in plain text. Data is transmitted over encrypted connections.</p>

        <h2>5. Your Rights</h2>
        <p>You can request access, correction, or deletion of your data anytime by contacting us or through your account settings.</p>

        <h2>6. Cookies</h2>
        <p>We use minimal cookies for session/auth purposes. Analytics cookies can be opted out of anytime.</p>
      </div>
    </div>
  `,
  styles: [`
    .legal-page { min-height:100vh; background:var(--bg); color:var(--white); display:flex; justify-content:center; padding:60px 20px; font-family:'Poppins',sans-serif; }
    .legal-card { max-width:680px; width:100%; }
    .legal-back { color:var(--gray); text-decoration:none; font-size:14px; }
    h1 { margin:16px 0 4px; font-size:32px; }
    .legal-updated { color:var(--gray-dim); font-size:13px; margin-bottom:28px; }
    h2 { color:var(--gold-light); font-size:16px; margin:24px 0 8px; }
    p { color:var(--gray); line-height:1.6; font-size:14.5px; }
  `]
})
export class PrivacyComponent {}
